/* ══════════════════════════════
   CINEMATIC CANVAS — Hero BG
══════════════════════════════ */
function CinematicCanvas() {
  const ref = useRef(null);
  const animRef = useRef(null);
  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const resize = () => { canvas.width = canvas.offsetWidth; canvas.height = canvas.offsetHeight; };
    resize();
    window.addEventListener("resize", resize);

    // Layer 1: background slow large nodes
    const bgNodes = Array.from({ length: 30 }, () => ({
      x: Math.random() * canvas.width, y: Math.random() * canvas.height,
      vx: (Math.random() - 0.5) * 0.18, vy: (Math.random() - 0.5) * 0.18,
      r: Math.random() * 3 + 2, o: Math.random() * 0.2 + 0.08, pulse: Math.random() * Math.PI * 2,
    }));
    // Layer 2: foreground fast small nodes
    const fgNodes = Array.from({ length: 55 }, () => ({
      x: Math.random() * canvas.width, y: Math.random() * canvas.height,
      vx: (Math.random() - 0.5) * 0.45, vy: (Math.random() - 0.5) * 0.45,
      r: Math.random() * 1.8 + 0.6, o: Math.random() * 0.55 + 0.25, pulse: Math.random() * Math.PI * 2,
    }));

    let tick = 0;
    const MAX_BG = 260, MAX_FG = 140;

    const draw = () => {
      tick++;
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // bg connections
      ctx.lineWidth = 0.5;
      for (let i = 0; i < bgNodes.length; i++) {
        const n = bgNodes[i];
        n.x += n.vx; n.y += n.vy;
        if (n.x < 0 || n.x > canvas.width) n.vx *= -1;
        if (n.y < 0 || n.y > canvas.height) n.vy *= -1;
        n.pulse += 0.018;
        const pr = n.r + Math.sin(n.pulse) * 1.2;
        ctx.shadowBlur = 12; ctx.shadowColor = "rgba(212,168,75,0.4)";
        ctx.beginPath(); ctx.arc(n.x, n.y, pr, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(212,168,75,${n.o * 0.6})`; ctx.fill();
        for (let j = i + 1; j < bgNodes.length; j++) {
          const dx = bgNodes[i].x - bgNodes[j].x, dy = bgNodes[i].y - bgNodes[j].y;
          const d = Math.sqrt(dx * dx + dy * dy);
          if (d < MAX_BG) {
            ctx.beginPath(); ctx.moveTo(bgNodes[i].x, bgNodes[i].y); ctx.lineTo(bgNodes[j].x, bgNodes[j].y);
            ctx.strokeStyle = `rgba(212,168,75,${(1 - d / MAX_BG) * 0.12})`; ctx.stroke();
          }
        }
      }

      // fg connections
      ctx.lineWidth = 0.8;
      for (let i = 0; i < fgNodes.length; i++) {
        const n = fgNodes[i];
        n.x += n.vx; n.y += n.vy;
        if (n.x < 0 || n.x > canvas.width) n.vx *= -1;
        if (n.y < 0 || n.y > canvas.height) n.vy *= -1;
        n.pulse += 0.028;
        const pr = n.r + Math.sin(n.pulse) * 0.7;
        ctx.shadowBlur = 18; ctx.shadowColor = "rgba(212,168,75,0.8)";
        ctx.beginPath(); ctx.arc(n.x, n.y, pr, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(212,168,75,${n.o})`; ctx.fill();
        ctx.shadowBlur = 0;
        for (let j = i + 1; j < fgNodes.length; j++) {
          const dx = fgNodes[i].x - fgNodes[j].x, dy = fgNodes[i].y - fgNodes[j].y;
          const d = Math.sqrt(dx * dx + dy * dy);
          if (d < MAX_FG) {
            ctx.beginPath(); ctx.moveTo(fgNodes[i].x, fgNodes[i].y); ctx.lineTo(fgNodes[j].x, fgNodes[j].y);
            ctx.strokeStyle = `rgba(212,168,75,${(1 - d / MAX_FG) * 0.38})`; ctx.stroke();
          }
        }
      }
      animRef.current = requestAnimationFrame(draw);
    };
    draw();
    return () => { window.removeEventListener("resize", resize); cancelAnimationFrame(animRef.current); };
  }, []);
  return <canvas ref={ref} style={{ position:"absolute",inset:0,width:"100%",height:"100%",opacity:0.75 }} />;
}

